style.css:
@-moz-document domain("roblox.com") {
/* Replace "Connections" with "Friends" in navigation links */
a[href*="connections"] {
    font-size: 0 !important;
}

a[href*="connections"]:after {
    content: "Friends";
    font-size: 14px !important;
}

/* Replace in profile stats */
.profile-stat a[href*="connections"] {
    text-indent: -9999px;
}

.profile-stat a[href*="connections"]:after {
    content: "Friends";
    text-indent: 0;
    display: block;
}

/* Replace in breadcrumbs */
.breadcrumb-item a[href*="connections"] {
    visibility: hidden;
}

.breadcrumb-item a[href*="connections"]:after {
    content: "Friends";
    visibility: visible;
}
}
